import logging
import os
import inspect
from ta_emss.utilities.trs.rlogger.RawFormatter import RawFormatter, ConnectionOpenRecordFilter

g_current_testcase = None
g_common_logging_handlers = {}
g_current_testcase_logging_handlers = {}
g_current_connections = {}

# new logging levels (above ERROR = 40, below CRITICAL = 50)
TEST_STEP = 43
TEST_CASE = 45
TEST_SUITE = 47


class ConnectionDirection_InjectionFilter(logging.Filter):
    def filter(self, record):
        if not hasattr(record, 'direction'):
            record.direction = ' '
        return True


def set_current_test_case(testcase_name):
    global g_current_testcase
    close_logs_of_current_test_case()

    g_current_testcase = testcase_name

    if g_current_testcase is not None:
        open_logs_of_current_test_case()
    else:
        open_logs_for_all_registered_connections()


def close_logs_of_current_test_case():
    logger = logging.getLogger("ruff")
    remove_logging_handlers(logger, g_current_testcase_logging_handlers)
    close_logs_of_all_registered_connections()


def open_logs_of_current_test_case():
    setup_new_file_handler(logger_name="ruff",
                           loglevel=logging.INFO,
                           log_filename=get_logname(type="testcase"),
                           formatter=logging.Formatter("%(asctime)s %(levelname)-10s: |%(message)s"),
                           handlers_storage=g_current_testcase_logging_handlers)
    open_logs_for_all_registered_connections()


def open_logs_for_all_registered_connections():
    for connection_name in g_current_connections.keys():
        assert g_current_connections[connection_name] is None
        cfhs = open_connection_log_handlers(connection_name)
        g_current_connections[connection_name] = cfhs


def close_logs_of_all_registered_connections():
    for connection_name in g_current_connections.keys():
        close_connection_log_handlers(connection_name)


def remove_connections_logging_handlers():
    for connection_name in g_current_connections.keys():
        unregister_connection(connection_name)


def register_connection(connection_name, debug=False):
    if connection_name not in g_current_connections:
        cfhs = open_connection_log_handlers(connection_name)
        g_current_connections[connection_name] = cfhs


def unregister_connection(connection_name):
    close_connection_log_handlers(connection_name)
    del g_current_connections[connection_name]


def open_connection_log_handlers(connection_name):
    try:
        logging_handlers = g_current_testcase_logging_handlers if g_current_testcase else g_common_logging_handlers
        cfh = setup_new_file_handler(logger_name=("ruff.connection.%s" % connection_name),
                                     loglevel=logging.INFO,
                                     log_filename=get_logname(type="connection", instance=connection_name),
                                     formatter=logging.Formatter("%(asctime)s %(direction)s|%(message)s"),
                                     handlers_storage=logging_handlers)
        direction_inject = ConnectionDirection_InjectionFilter()
        cfh.addFilter(direction_inject)

        created_fhandlers = [cfh]
    except Exception as exc:
        print("Cannot create logging handler: {}".format(exc))
        created_fhandlers = []

    if bool(int(os.getenv('RUFF_RECORD', '0'))):
        cfh_raw = setup_new_file_handler(logger_name=("ruff.connection.%s" % connection_name),
                                         loglevel=logging.INFO,
                                         log_filename=get_logname(type="connection_raw", instance=connection_name),
                                         formatter=logging.Formatter(fmt="%(message)s"),
                                         handlers_storage=logging_handlers)
        cfh_raw.addFilter(ConnectionOpenRecordFilter())

        cfh_raw_time = setup_new_file_handler(logger_name=("ruff.connection.%s" % connection_name),
                                              loglevel=logging.INFO,
                                              log_filename=get_logname(type="connection_raw_time", instance=connection_name),
                                              formatter=RawFormatter(fmt="%(timestamp)s|%(byte_length)8s |%(pkg_type)s %(epoch_time)-s |"),
                                              handlers_storage=logging_handlers)
        created_fhandlers.extend([cfh_raw, cfh_raw_time])

    return created_fhandlers


def close_connection_log_handlers(connection_name):
    try:
        logger = logging.getLogger("ruff.connection.%s" % connection_name)
        for connection_fh in g_current_connections[connection_name]:
            logger.removeHandler(connection_fh)
            connection_fh.close()
            if connection_fh in g_common_logging_handlers:
                del g_common_logging_handlers[connection_fh]
        g_current_connections[connection_name] = None
    except KeyError:
        pass


def setup_new_file_handler(logger_name, loglevel, log_filename, handlers_storage, formatter):
    logger = logging.getLogger(logger_name)
    logger.setLevel(logging.DEBUG)
    logger.propagate = False
    cfh = logging.FileHandler(log_filename)
    cfh.setLevel(loglevel)
    cfh.setFormatter(formatter)
    add_logging_handler(logger, cfh, handlers_storage)
    return cfh


def add_logging_handler(logger, handler, handlers_storage):
    logger.addHandler(handler)
    handlers_storage[str(handler)] = handler


def remove_logging_handlers(logger, handlers_storage):
    for handler in handlers_storage.values():
        logger.removeHandler(handler)
        handler.close()
        del handlers_storage[str(handler)]


def get_logs_folder():
    default_logdir = os.path.join(os.path.expanduser("~"), "ruff_startup", "logs")
    return os.getenv('RUFF_LOGDIR', default_logdir)


def get_logname(type, instance='', for_testcase=''):
    '''
    :param type:     "testsession" or "librarydebug" or "testcase" (means current) or "connection"
    :param instance: registered connection name (required for type "connection")
    :return:         logname of most important logs created by ruff library
    '''
    logdir = get_logs_folder()

    if type == "testsession":
        return os.path.join(logdir, "tests_run.log")
    elif type == "librarydebug":
        return os.path.join(logdir, "ruff_debug.log")
    elif type == "testcase":
        tc_name = g_current_testcase if g_current_testcase else "no_current_TC"
        return os.path.join(logdir, "{}.rlog".format(tc_name))
    elif type == "connection":
        if for_testcase:
            return os.path.join(logdir, "{}--{}.rlog".format(for_testcase, instance))
        elif g_current_testcase:
            return os.path.join(logdir, "{}--{}.rlog".format(g_current_testcase, instance))
        else:
            return os.path.join(logdir, "connection--{}.rlog".format(instance))
    elif type == "connection_raw":
        # raw logs of connection are not split per TC
        return os.path.join(logdir, "connection--{}.raw".format(instance))
    elif type == "connection_raw_time":
        # raw logs of connection are not split per TC
        return os.path.join(logdir, "connection--{}.raw.time".format(instance))


def get_testcase_logset():
    '''
    :return: all logs belonging to current test case
    '''
    if g_current_testcase:
        logset = [get_logname("testcase")] + [get_logname("connection", conn_name) for conn_name in g_current_connections]
        return logset
    else:
        return []


def init_logsystem():
    logger = logging.getLogger("ruff")
    logger.setLevel(logging.DEBUG)
    logger.propagate = False
    install_new_loglevels()
    prepare_logs_folder()
    load_default_configuration()


def close_logsystem():
    main_logger = logging.getLogger("ruff")
    remove_logging_handlers(main_logger, g_current_testcase_logging_handlers)
    remove_logging_handlers(main_logger, g_common_logging_handlers)
    remove_connections_logging_handlers()


def reload_logsystem():
    close_logsystem()
    init_logsystem()


def install_new_loglevels():
    logging.addLevelName(TEST_STEP, "TEST_STEP")
    logging.addLevelName(TEST_CASE, "TEST_CASE")
    logging.addLevelName(TEST_SUITE, "TEST_SUITE")


def prepare_logs_folder():
    logdir = get_logs_folder()
    if not os.path.exists(logdir):
        os.makedirs(logdir)


def load_default_configuration():
    activate_testsession_log()
    if bool(int(os.getenv('RUFF_DEBUG', '0'))):
        activate_debugging_log()


def activate_testsession_log():
    setup_new_file_handler(logger_name="ruff",
                           loglevel=TEST_CASE,
                           log_filename=get_logname(type="testsession"),
                           formatter=logging.Formatter("%(asctime)s %(levelname)-10s: %(message)s"),
                           handlers_storage=g_common_logging_handlers)


def activate_debugging_log():
    setup_new_file_handler(logger_name="ruff",
                           loglevel=logging.DEBUG,
                           log_filename=get_logname(type="librarydebug"),
                           formatter=logging.Formatter("%(asctime)s %(levelname)-10s %(filename)s, %(lineno)d, %(funcName)s: %(message)s"),
                           handlers_storage=g_common_logging_handlers)


class CallerLocation_InjectionFilter(logging.Filter):
    def __init__(self):
        self.no_injection()

    def no_injection(self):
        self.pathname = ''
        self.lineno = -1
        self.funcName = ''
        self.filename = ''
        self.module = ''

    def should_inject(self):
        return self.lineno > -1

    def filter(self, record):
        if self.should_inject():
            record.pathname = self.pathname
            record.lineno = self.lineno
            record.funcName = self.funcName
            record.filename = self.filename
            record.module = self.module
            self.no_injection()  # injection is one-shot, for one log record only
        return True

    def inject_codelocation_of_my_caller(self):
        """
        Takes code location of caller of this function caller
        This will be injected in log record
        """
        (caller_frame_obj, pathname, lineno, funcName, src_context_lines, curr_line_idx) = inspect.stack()[2]
        self.pathname = pathname
        self.lineno = lineno
        self.funcName = funcName
        try:
            self.filename = os.path.basename(pathname)
            self.module = os.path.splitext(self.filename)[0]
        except (TypeError, ValueError, AttributeError):
            self.filename = pathname
            self.module = "Unknown module"


reload_logsystem()
